import { z } from 'zod';

// Base interface for direct email sending (requires subject)
export interface BaseEmailPayload {
  to: string;
  subject: string;
  html?: string;
  text?: string;
  type?: string;
}

// Interface for template-based emails (subject generated by template)
export interface BaseTemplatedEmailPayload {
  to: string;
  subject?: string; // Optional because templates generate this
  html?: string;
  text?: string;
  type?: string;
}

// For direct email sending via sendEmail()
export type EmailPayload = BaseEmailPayload &
  (
    | {
        html: string;
        text?: string;
      }
    | {
        html?: string;
        text: string;
      }
  );

// For template-based verification/invite emails
export type TokenBasedEmailPayload = BaseTemplatedEmailPayload & {
  name: string;
} & (
    | {
        token: string;
        url?: string;
      }
    | { token?: string; url: string }
  );

export const urlType = z.enum([
  'verify-email',
  'reset-password',
  'accept-invite',
]);
export type UrlType = z.infer<typeof urlType>;

export type UrlParams = {
  token: string;
} & Record<string, string | undefined>;

export type InviteEmailPayload = TokenBasedEmailPayload & {
  invitedByUser: { firstname: string; email: string };
  invitedByOrg: { name: string };
};

type VerifyEmailInput = {
  token: string;
  userId: string;
};

type ResetPasswordParams = {
  token: string;
  email: string;
};

type AcceptInviteParams = VerifyEmailInput;

export type UrlParamMap = {
  'verify-email': VerifyEmailInput;
  'reset-password': ResetPasswordParams;
  'accept-invite': AcceptInviteParams;
};
